def recipe_to_ts(recipe):
    """Convert a recipe dict to TypeScript object string"""
    lines = ['  {']
    
    # Simple fields
    for key in ['id', 'slug', 'title', 'shortTitle', 'description', 'image', 'kategori', 'waktu', 'porsi', 'kesulitan', 'rating', 'origin']:
        if key in recipe:
            val = recipe[key]
            if isinstance(val, str):
                val = val.replace('\\', '\\\\').replace('"', '\\"')
                lines.append(f'    {key}: "{val}",')
            elif isinstance(val, (int, float)):
                lines.append(f'    {key}: {val},')
    
    # Array fields
    for json_key, ts_key in [('bahan', 'ingredients'), ('ingredients', 'ingredients'), ('cara_buat', 'instructions'), ('instructions', 'instructions')]:
        if json_key in recipe and isinstance(recipe[json_key], list):
            lines.append(f'    {ts_key}: [')
            for item in recipe[json_key]:
                item = item.replace('\\', '\\\\').replace('"', '\\"')
                lines.append(f'      "{item}",')
            lines.append('    ],')
            break
    
    # String fields
    field_map = {
        'tips': 'tips', 'sejarah': 'detailedHistory', 'variasi_daerah': 'regionalVariations',
        'teknik_memasak': 'cookingTechnique', 'profil_gizi': 'nutritionalProfile',
        'detailedHistory': 'detailedHistory', 'culturalSignificance': 'culturalSignificance',
        'regionalVariations': 'regionalVariations', 'cookingTechnique': 'cookingTechnique',
        'nutritionalProfile': 'nutritionalProfile'
    }
    
    for json_key, ts_key in field_map.items():
        if json_key in recipe and isinstance(recipe[json_key], str) and recipe[json_key]:
            val = recipe[json_key].replace('\\', '\\\\').replace('"', '\\"')
            lines.append(f'    {ts_key}: "{val}",')
    
    lines.append('  }')
    return '\n'.join(lines)


